import { test, expect } from '@playwright/test';

test.describe('Homepage Hero Section Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display mobile-friendly hero section on mobile devices', async ({ page }) => {
    // Set viewport to mobile
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify hero section is visible on mobile
    const heroSection = page.getByRole('region', { name: /hero/i });
    await expect(heroSection).toBeVisible();

    // Verify hero image is responsive and fills the viewport
    const heroImage = page.getByRole('img', { name: /hero image/i });
    await expect(heroImage).toBeVisible();
    await expect(heroImage).toHaveAttribute('src', /hero-mobile-image/i);

    // Verify hero text is readable and styled appropriately
    const heroHeading = page.getByRole('heading', { name: /hero heading/i });
    await expect(heroHeading).toBeVisible();
    await expect(heroHeading).toHaveTextContent('Welcome to Our Site');

    // Verify hero button is visible and accessible
    const heroButton = page.getByRole('button', { name: /sign up/i });
    await expect(heroButton).toBeVisible();

    // Verify hero section has appropriate padding and margins
    const heroPadding = page.getByRole('region', { name: /hero/i }).boundingBox();
    expect(heroPadding).toBeGreaterThan(0);

    // Verify hero section has correct background color
    const heroBackgroundColor = page.getByRole('region', { name: /hero/i }).evaluate((el) => window.getComputedStyle(el).backgroundColor);
    expect(heroBackgroundColor).toBe('rgb(255, 255, 255)');
  });

  test('should display desktop-friendly hero section on desktop devices', async ({ page }) => {
    // Set viewport to desktop
    await page.setViewportSize({ width: 1280, height: 720 });

    // Verify hero section is visible on desktop
    const heroSection = page.getByRole('region', { name: /hero/i });
    await expect(heroSection).toBeVisible();

    // Verify hero image is responsive and does not overflow
    const heroImage = page.getByRole('img', { name: /hero image/i });
    await expect(heroImage).toBeVisible();
    await expect(heroImage).toHaveAttribute('src', /desktop-hero-image/i);

    // Verify hero text is readable and styled appropriately
    const heroHeading = page.getByRole('heading', { name: /hero heading/i });
    await expect(heroHeading).toBeVisible();
    await expect(heroHeading).toHaveTextContent('Welcome to Our Site');

    // Verify hero button is visible and accessible
    const heroButton = page.getByRole('button', { name: /sign up/i });
    await expect(heroButton).toBeVisible();

    // Verify hero section has appropriate padding and margins
    const heroPadding = page.getByRole('region', { name: /hero/i }).boundingBox();
    expect(heroPadding).toBeGreaterThan(0);

    // Verify hero section has correct background color
    const heroBackgroundColor = page.getByRole('region', { name: /hero/i }).evaluate((el) => window.getComputedStyle(el).backgroundColor);
    expect(heroBackgroundColor).toBe('rgb(255, 255, 255)');
  });
});
